const position = globalContext.componentPositionInfo?.['feed_fetch'];
if (!position) { return false; }

// Отступ в пикселях (чем больше число, тем раньше сработает)
const offset = 200;

// Нижняя граница объекта должна быть ниже верхнего края экрана + отступ
const isBelowTop = position.y + position.height > window.scrollY - offset;

// Верхняя граница объекта должна быть выше нижнего края экрана + отступ
const isAboveBottom = position.y < window.scrollY + window.innerHeight + offset;

return isBelowTop && isAboveBottom;




