const allStories = collections['a4408848-c4d6-452b-ad2d-e143dcf0c0bb']?.['data'] || [];

// Группируем по theme и берем первую запись из каждой группы
const uniqueStories = [];
const seenThemes = new Set();

allStories.forEach(story => {
    const theme = story?.theme;
    if (theme && !seenThemes.has(theme)) {
        seenThemes.add(theme);
        uniqueStories.push(story);
    }
});

return uniqueStories;

