const currentTheme = variables['6512d163-78e4-446e-bbaf-fb9538a5f106'];
const allStories = collections['a4408848-c4d6-452b-ad2d-e143dcf0c0bb']?.['data'] || [];

// Получаем уникальные темы
const uniqueThemes = [...new Set(allStories.map(story => story?.theme).filter(Boolean))];

// Находим индекс текущей темы
const currentIndex = uniqueThemes.indexOf(currentTheme);

// Определяем следующую тему
let nextTheme;
if (currentIndex === -1 || currentIndex === uniqueThemes.length - 1) {
    // Если тема не найдена или это последняя тема - берем первую
    nextTheme = uniqueThemes[0] || currentTheme;
} else {
    // Иначе берем следующую тему
    nextTheme = uniqueThemes[currentIndex + 1];
}

// Возвращаем следующую тему для установки в переменную
return nextTheme;

