    if (!str) return "";

    const map = {
        1: "i",
        2: "ii",
        3: "iii",
        4: "iv",
        5: "v",
        6: "vi",
        7: "vii",
        8: "viii",
        9: "ix",
        10: "x"
    };

    return str
        .toLowerCase()
        .replace(/\b([1-9]|10)\b/g, m => map[m] || m)
        .trim();
}

